// Embedded base64 team photographs for instant, zero-latency rendering
// Guaranteed to display on live website even before Firestore sync or in offline mode

export const DR_DK_AGRAWAL_PHOTO = 'data:image/jpeg;base64,';
export const SWATI_SOAM_PHOTO = 'data:image/jpeg;base64,';

export function getFallbackTeamPhoto(memberIdOrName: string): string {
  const lower = (memberIdOrName || '').toLowerCase();
  if (lower.includes('agrawal') || lower.includes('dk') || lower.includes('founder')) {
    return DR_DK_AGRAWAL_PHOTO;
  }
  if (lower.includes('soam') || lower.includes('swati') || lower.includes('co-founder')) {
    return SWATI_SOAM_PHOTO;
  }
  return '';
}
